var a=`0979-kimbap`;var s=`world-0979`;var n=`KR`;var t=`east-asia`;var o=8;var r=67;var d={en:`Kimbap`,ua:`Кімбап`};var c={en:`Kimbap is a South Korea dish made with calrose rice, carrot, spinach, chicken egg. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кімбап, страва кухні країни Південна Корея. Основні складники: рис калроуз, морква, шпинат, куряче яйце. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 23 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 23 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:23,i:[[`calrose-rice`,450,`g`],[`water`,790,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`carrot`,160,`g`],[`spinach`,180,`g`],[`chicken-egg`,2,`pcs`],[`canola-oil`,35,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`pickled-daikon`,150,`g`],[`cucumber`,170,`g`],[`cooked-ham`,200,`g`]]},{en:`Spread warm sesame-seasoned rice on nori and arrange cooked fillings in stripes; roll firmly and cut kimbap into neat rounds.`,ua:`Розподіліть теплий рис із кунжутною олією на норі, викладіть готові начинки смугами, туго скрутіть і наріжте кімбап рівними кружальцями.`,t:[`rolling-stuffed-food`],m:22,i:[[`nori`,9,`pcs`],[`toasted-sesame-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,20,`g`]]}];var g={slug:a,id:s,country:`KR`,region:t,servings:8,minutes:67,title:d,text:c,steps:l};export{n as country,g as default,s as id,r as minutes,t as region,o as servings,a as slug,l as steps,c as text,d as title};